arguments.command:
TOTAL_REQUESTS=$(wc -l < access_log);
UNIQUE_IPS=$(awk '{print $1}' access_log | sort -u | wc -l);
FOUR_OH_FOUR=$(grep -c ' 404 ');

# Get Top 3 URLs
TOP_URLS=$(awk -F'"' '{print $2}' access_log | awk '{print $2}' | sort | uniq -c | sort -nr | head -3);

echo "Total requests: $TOTAL_REQUESTS" > report.txt;
echo "Unique IP addresses: $UNIQUE_IPS" >> report.txt;
echo "Top 3 URLs:" >> report.txt;
echo "$TOP_URLS" | while read COUNT URL; do
    echo "  $URL: $COUNT" >> report.txt
done;
echo "404 errors: $FOUR_OH_FOUR" >> report.txt

